#!/usr/bin/env python3
"""Restore assets/app.ico for Windows GUI."""
from pathlib import Path
import base64

ROOT = Path(__file__).resolve().parent
ICO_B64 = """"""


def main() -> None:
    path = ROOT / "app.ico"
    path.write_bytes(base64.b64decode(ICO_B64))
    print("OK", path, path.stat().st_size)


if __name__ == "__main__":
    main()
